import os
for r,d,f in os.walk('studies'):
    for x in f: print(os.path.join(r,x), os.path.getsize(os.path.join(r,x)))

import gzip,glob
for f in sorted(glob.glob('studies/data/raw/*series_matrix*')):
    print('=====',f)
    for l in gzip.open(f,'rt',errors='ignore'):
        if l.startswith('!series_matrix_table_begin'):break
        if any(l.startswith(k) for k in ['!Series_title','!Series_summary','!Series_overall','!Sample_title','!Sample_source','!Sample_characteristics','!Sample_treatment','!Sample_platform','!Series_platform','!Sample_data_processing','!Sample_label','!Sample_molecule']):
            print(l[:1200].rstrip())

import gzip,glob
from collections import Counter
for f in sorted(glob.glob('studies/data/raw/*series_matrix*')):
    print('=====',f)
    for l in gzip.open(f,'rt',errors='ignore'):
        if l.startswith('!series_matrix_table_begin'):break
        if l.startswith('!Series_'):
            if any(k in l for k in ['title','summary','overall_design','platform_id','type']): print(l[:1500].rstrip())
        elif l.startswith('!Sample_') and not any(k in l[:30] for k in ['geo_acc','contact','supplementary','date','status','relation','taxid','organism','channel','row','label_protocol','hyb','scan','extract','description','data_row']):
            vals=l.rstrip().split('\t'); c=Counter(v.strip('"') for v in vals[1:])
            print(vals[0], dict(list(c.items())[:40]) if len(c)<40 else f'{len(c)} unique; e.g. '+str(list(c)[:10]))

